use vstd::prelude::*;

verus! {

    // Given a sequence of chars `word`, returns its plural:
    // if it ends in 's' → append 'e','s'; otherwise append 's'.
    spec fn plural(word: Seq<char>) -> Seq<char>
        decreases word
    {
        if word.len() > 0 && word[word.len() - 1] == 's' {
            word.push('e').push('s')
        } else {
            word.push('s')
        }
    }

    // User‐facing function: non‐empty Vec<char> of a..z → plural as Vec<char>
    fn solve(s: &Vec<char>) -> (result: Vec<char>)
        requires
            s.len() > 0,
            forall |i: usize| i < s.len() ==> 'a' <= s[i] && s[i] <= 'z',
        ensures
            result.to_seq() == plural(to_seq(s))
    {
        // Clone the original word
        let mut result = s.clone();
        // If it ends in 's', push "es", else push "s"
        if s[s.len() - 1] == 's' {
            result.push('e');
            result.push('s');
        } else {
            result.push('s');
        }
        result
    }

}

